<section class="admin-card">
    <div class="admin-toolbar"><div><h2>Food items</h2><p class="admin-muted">Paused items stay available in admin but are hidden from the public menu.</p></div><a class="admin-btn" href="add-food.php"><i class="bi bi-plus-lg" aria-hidden="true"></i> Add item</a></div>
    <?php if ($foods) { ?>
        <nav class="admin-category-status-tabs" aria-label="Food item status">
            <?php foreach (array('all'=>'All', 'active'=>'Active', 'inactive'=>'Inactive') as $status => $label) { ?><a href="menu.php?tab=items&amp;item_status=<?php echo $status; ?>"<?php echo $itemStatus === $status ? ' aria-current="page"' : ''; ?>><?php echo $label; ?><span><?php echo $foodCounts[$status]; ?></span></a><?php } ?>
        </nav>
        <div class="admin-list-tools admin-item-tools">
            <label><i class="bi bi-search" aria-hidden="true"></i><input id="menu-item-search" type="search" placeholder="Search menu items" autocomplete="off"></label>
            <label class="admin-select-tool"><i class="bi bi-funnel" aria-hidden="true"></i><select id="menu-item-category" aria-label="Filter food items by category"><option value="all">All categories</option><?php foreach ($categories as $category) { ?><option value="<?php echo adminEscape($category['name']); ?>"><?php echo adminEscape($category['name']); ?></option><?php } ?></select></label>
            <button type="button" class="admin-btn secondary" id="menu-item-reset" hidden><i class="bi bi-arrow-counterclockwise" aria-hidden="true"></i> Reset</button>
        </div>
        <div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Image</th><th>Name</th><th>Category</th><th>Price</th><th>Status</th><th>Actions</th></tr></thead><tbody id="admin-menu-item-list"><?php foreach ($visibleFoods as $food) { ?><tr data-category="<?php echo adminEscape($food['category']); ?>"><td><?php if (!empty($food['picture'])) { ?><img src="../<?php echo adminEscape($food['picture']); ?>" alt=""><?php } else { ?><i class="bi bi-image admin-muted" aria-hidden="true"></i><?php } ?></td><td><strong><?php echo adminEscape($food['name']); ?></strong><br><span class="admin-muted"><?php echo adminEscape($food['description']); ?></span></td><td><?php echo adminEscape($food['category']); ?></td><td>Rs <?php echo number_format((float) $food['price']); ?></td><td><form method="post" class="admin-inline"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="food_id" value="<?php echo (int) $food['id']; ?>"><button class="admin-status-toggle <?php echo $food['is_active'] ? 'is-active' : ''; ?>" type="submit" name="toggle_food_status" title="<?php echo $food['is_active'] ? 'Pause menu item' : 'Activate menu item'; ?>" aria-label="<?php echo $food['is_active'] ? 'Pause menu item' : 'Activate menu item'; ?>"><i class="bi <?php echo $food['is_active'] ? 'bi-toggle-on' : 'bi-toggle-off'; ?>" aria-hidden="true"></i></button></form></td><td><div class="admin-actions"><a class="admin-icon-button" href="add-food.php?edit=<?php echo (int) $food['id']; ?>" title="Edit menu item" aria-label="Edit <?php echo adminEscape($food['name']); ?>"><i class="bi bi-pencil-square" aria-hidden="true"></i></a><form method="post" class="admin-inline" onsubmit="return confirm('Delete this menu item?')"><input type="hidden" name="csrf" value="<?php echo adminEscape(adminToken()); ?>"><input type="hidden" name="id" value="<?php echo (int) $food['id']; ?>"><button class="admin-icon-button danger" name="delete" title="Delete menu item" aria-label="Delete <?php echo adminEscape($food['name']); ?>"><i class="bi bi-trash" aria-hidden="true"></i></button></form></div></td></tr><?php } ?></tbody></table></div>
        <p class="admin-category-empty" id="menu-item-empty" hidden><i class="bi bi-search" aria-hidden="true"></i> No menu items match this search or category.</p>
        <nav class="admin-pagination" id="menu-item-pagination" aria-label="Food item pagination"></nav>
    <?php } else { ?><p class="admin-muted">No menu items found.</p><?php } ?>
</section>
<script>(function(){const rows=Array.from(document.querySelectorAll('#admin-menu-item-list tr')),search=document.getElementById('menu-item-search'),category=document.getElementById('menu-item-category'),reset=document.getElementById('menu-item-reset'),empty=document.getElementById('menu-item-empty'),pager=document.getElementById('menu-item-pagination');if(!rows.length||!search||!category||!reset||!empty||!pager)return;const pageSize=10;let page=1;function render(){const query=search.value.trim().toLowerCase(),selected=category.value,visible=rows.filter(function(row){return(selected==='all'||row.dataset.category===selected)&&row.textContent.toLowerCase().includes(query)}),pages=Math.max(1,Math.ceil(visible.length/pageSize));if(page>pages)page=pages;rows.forEach(function(row){row.hidden=true});visible.slice((page-1)*pageSize,page*pageSize).forEach(function(row){row.hidden=false});empty.hidden=visible.length>0;reset.hidden=query===''&&selected==='all';const numbers=Array.from({length:pages},function(_,i){return i+1}).filter(function(n){return n===1||n===pages||Math.abs(n-page)<=1});pager.hidden=pages<=1;pager.innerHTML=pages>1?numbers.map(function(n,i){const prior=numbers[i-1],gap=prior&&n-prior>1?'<span aria-hidden="true">...</span>':'';return gap+'<button type="button" class="'+(n===page?'active':'')+'" data-page="'+n+'"'+(n===page?' aria-current="page"':'')+'>'+n+'</button>'}).join(''):''}search.addEventListener('input',function(){page=1;render()});category.addEventListener('change',function(){page=1;render()});reset.addEventListener('click',function(){search.value='';category.value='all';page=1;render();search.focus()});pager.addEventListener('click',function(event){const button=event.target.closest('[data-page]');if(button){page=Number(button.dataset.page);render()}});render()}());</script>
